import {AlertTriangle,CalendarClock,Camera,CarFront,ChevronRight,Euro,PhoneCall,Users,Wrench} from 'lucide-react'
import {buildPriorities,type PriorityItem} from '../domain/priorities'
import type {TenantData,View} from '../types'
const icon={PRICE:Euro,PHOTO:Camera,WORK:Wrench,AGE:CarFront,CALENDAR:CalendarClock,CUSTOMER:PhoneCall,DELIVERY:AlertTriangle}
export function TodayPage({data,onVehicle,onView}:{data:TenantData;onVehicle:(id:string)=>void;onView:(view:View)=>void}){const priorities=buildPriorities(data);const stock=data.vehicles.filter(v=>!['CONSEGNATA','VENDUTA','ANNULLATA'].includes(v.status||''));const customerActions=priorities.filter(p=>p.kind==='CUSTOMER').length;const calendarActions=priorities.filter(p=>p.kind==='CALENDAR').length;const act=(p:PriorityItem)=>{if(p.kind==='CUSTOMER'){onView('clients');return}if(p.kind==='CALENDAR'){onView('calendar');return}if(p.vehicleId){onVehicle(p.vehicleId);return}if(p.customerId)onView('clients')};const actionLabel=(p?:PriorityItem)=>p?.kind==='CUSTOMER'?'Apri clienti':p?.kind==='CALENDAR'?'Apri calendario':p?.vehicleId?'Apri auto':'Apri';return <><div className="page-heading"><div><p className="eyebrow">COMANDO OPERATIVO</p><h1>Oggi</h1><p>{priorities.length?`${priorities.length} azioni concrete da gestire.`:'Nessun blocco urgente. Puoi lavorare sul commerciale.'}</p></div><div className="mini-stat"><span>AUTO ATTIVE</span><b>{stock.length}</b></div></div><div className="today-kpis"><button onClick={()=>onView('clients')}><Users/><span><b>{customerActions}</b><small>Clienti da ricontattare</small></span></button><button onClick={()=>onView('calendar')}><CalendarClock/><span><b>{calendarActions}</b><small>Scadenze / appuntamenti</small></span></button><button onClick={()=>onView('garage')}><CarFront/><span><b>{priorities.filter(p=>['PRICE','PHOTO','WORK','AGE'].includes(p.kind)).length}</b><small>Azioni sul Garage</small></span></button></div><section className="focus-card"><div><p className="eyebrow">PRIMA COSA DA FARE</p><h2>{priorities[0]?.title||'Niente di urgente 🎉'}</h2><p>{priorities[0]?.detail||'Puoi passare ai clienti o al Garage senza emergenze aperte.'}</p></div>{priorities[0]&&<button className="focus-cta" onClick={()=>act(priorities[0])}>{actionLabel(priorities[0])} <ChevronRight/></button>}</section><section className="section"><div className="section-title"><div><p className="eyebrow">CODA DI LAVORO</p><h2>Una lista, in ordine di urgenza</h2></div></div><div className="priority-list">{priorities.slice(0,12).map(p=>{const Icon=icon[p.kind];return <button key={p.id} onClick={()=>act(p)} className={`priority-row severity-${p.severity}`}><span className="priority-icon"><Icon/></span><span><b>{p.title}</b><small>{p.detail}</small></span><ChevronRight/></button>})}{!priorities.length&&<div className="empty-state">Nessuna azione urgente. Ottimo momento per seguire nuovi clienti.</div>}</div></section></>}
